-- In-App AI Assistant, Part 1 (seed): a starting knowledge base
-- covering the most common "how do I" topics. Not exhaustive --
-- scoped to features confirmed accurate (built/verified this session,
-- or directly read in the codebase), rather than guessing at details
-- for older features not directly verified. Grows over time: every
-- future feature should ship with a matching row update here, same
-- discipline as the version.txt bump.

begin;

-- One copy of this starter content per existing tenant (tenant_id has
-- no usable default here -- current_tenant_id() resolves off session
-- context a migration script doesn't have) -- a reasonable shared
-- baseline; a tenant's own Super Admin can edit/override their copy
-- later via this table's existing write policy.
insert into public.assistant_knowledge_base (topic, content_en, content_fr, audience, tenant_id)
select v.topic, v.content_en, v.content_fr, v.audience, t.id
from (values

('Submitting a prayer request', 'From the sidebar''s "More" menu, choose "Prayer Request". Type your request and optionally check "Submit anonymously" so your name isn''t attached. You can see your own past requests and whether they''ve been prayed for at the bottom of that same screen.', 'Dans le menu "Plus" de la barre latérale, choisissez "Requête de prière". Saisissez votre requête et cochez éventuellement "Soumettre anonymement" pour que votre nom n''y soit pas associé. Vous pouvez voir vos propres requêtes passées et si elles ont été priées en bas du même écran.', 'everyone'),

('Reporting an absence', 'From the sidebar, choose "Report Absence" (visible once you belong to at least one department). Pick the date(s) you''ll miss and submit -- this notifies the departments you''re part of.', 'Dans la barre latérale, choisissez "Signaler une absence" (visible une fois que vous appartenez à au moins un département). Choisissez la ou les dates que vous manquerez et soumettez -- cela avertit les départements dont vous faites partie.', 'everyone'),

('Booking a meeting with the pastor', 'From the sidebar, choose "Pastor Meeting" (or open it from the Pastoral Dashboard''s "Pastor Meetings" tab if you already have access there). Pick an available time slot, in-person or online, and confirm -- you''ll see it listed under "My Requests".', 'Dans la barre latérale, choisissez "Rendez-vous pastoral" (ou ouvrez-le depuis l''onglet "Rendez-vous pastoraux" du Tableau de bord pastoral si vous y avez déjà accès). Choisissez un créneau disponible, en personne ou en ligne, et confirmez -- vous le verrez apparaître sous "Mes demandes".', 'everyone'),

('Joining a department', 'From the sidebar, choose "Join Department" and select the one you want to join. A department admin needs to approve the request before you''re fully a member (except in a department you''re assigned admin/secretary of directly).', 'Dans la barre latérale, choisissez "Rejoindre un département" et sélectionnez celui que vous souhaitez rejoindre. Un administrateur du département doit approuver la demande avant que vous en soyez pleinement membre.', 'everyone'),

('The Pastoral Dashboard', 'Reachable from the sidebar''s Tools menu (or a Quick Access tile, if you have pastoral/department-admin access) -- it brings together Prayer Requests, Urgent Prayer Cases, Member Cases, Guest Cases, Account Claims, Attendance, and Pastor Meetings in one page with tabs. Only the sections you actually have access to are shown.', 'Accessible depuis le menu Outils de la barre latérale (ou une tuile d''Accès rapide, si vous avez un accès pastoral/administrateur de département) -- il regroupe les Requêtes de prière, les Cas de prière urgents, les Dossiers des membres, les Dossiers des visiteurs, les Demandes de compte, les Présences et les Rendez-vous pastoraux dans une seule page à onglets. Seules les sections auxquelles vous avez réellement accès sont affichées.', 'pastoral'),

('Creating an Urgent Prayer Case', 'From the Pastoral Dashboard''s "Urgent Prayer Cases" tab, click "New Case". Pick an existing member or type a name freely, describe the need, and optionally share it with specific other admins -- only you, oversight roles, and anyone you explicitly share it with can see it.', 'Depuis l''onglet "Cas de prière urgents" du Tableau de bord pastoral, cliquez sur "Nouveau cas". Choisissez un membre existant ou saisissez un nom librement, décrivez le besoin, et partagez-le éventuellement avec d''autres administrateurs précis -- seuls vous, les rôles de supervision et les personnes avec qui vous l''avez explicitement partagé peuvent le voir.', 'pastoral'),

('Creating a Member Case', 'From the Pastoral Dashboard''s "Member Cases" tab, click "New Case", pick the member, and write a note describing what follow-up is needed. You can send it to a specific department, and it keeps a full transfer history as it moves between departments. You can also add/update the note on a case after it''s already created.', 'Depuis l''onglet "Dossiers des membres" du Tableau de bord pastoral, cliquez sur "Nouveau dossier", choisissez le membre, et rédigez une note décrivant le suivi nécessaire. Vous pouvez l''envoyer à un département précis, et il conserve un historique complet de transfert. Vous pouvez aussi ajouter ou modifier la note après la création du dossier.', 'pastoral'),

('Guest Cases and follow-up', 'Guest/visitor leads (from attendance check-in or new sign-ups with no department yet) show up in the Pastoral Dashboard''s "Guest Cases" tab. Mark a follow-up call complete with a note, send the case to a department, or -- if the person has no login yet -- click "Create Account" to turn their already-captured info into a real account in one step.', 'Les pistes de visiteurs (venant de l''enregistrement de présence ou de nouvelles inscriptions sans département) apparaissent dans l''onglet "Dossiers des visiteurs" du Tableau de bord pastoral. Marquez un appel de suivi comme terminé avec une note, envoyez le dossier à un département, ou -- si la personne n''a pas encore de connexion -- cliquez sur "Créer un compte" pour transformer en un clic ses informations déjà saisies en un vrai compte.', 'pastoral'),

('Silent Users', 'A Silent user is a real person tracked for offerings, attendance and cases without a login -- useful for someone who gives or attends but isn''t ready for (or doesn''t want) an account yet. Create one from "Add User" by checking "No login yet (Silent user)". When they''re ready for a real account, creating one (by an admin or themselves signing up) checks for a name match and offers to carry their existing history over -- always with an explicit yes/no confirmation, never automatic.', 'Un utilisateur silencieux est une vraie personne suivie pour les offrandes, les présences et les dossiers sans connexion -- utile pour quelqu''un qui donne ou assiste mais n''est pas encore prêt pour un compte. Créez-en un depuis "Ajouter un utilisateur" en cochant "Pas encore de connexion (utilisateur silencieux)". Lorsque la personne est prête pour un vrai compte, la création d''un compte (par un administrateur ou par elle-même) vérifie une correspondance de nom et propose de transférer son historique existant -- toujours avec une confirmation explicite, jamais automatique.', 'pastoral'),

('Account Claims', 'When someone signs themselves up and their name closely matches an existing Silent user, but their email/phone doesn''t match what''s on file, it shows up here instead of merging automatically. Approve it to link the new account to that Silent record (history carries over), or reject it to create them as a brand-new, separate person.', 'Lorsqu''une personne s''inscrit elle-même et que son nom correspond étroitement à un utilisateur silencieux existant, mais que son courriel/téléphone ne correspond pas à ce qui est enregistré, cela apparaît ici au lieu d''être fusionné automatiquement. Approuvez pour lier le nouveau compte à ce dossier silencieux (l''historique est conservé), ou rejetez pour créer une personne distincte.', 'pastoral'),

('Recording attendance', 'The Pastoral Dashboard''s "Attendance" tab has two ways to check people in: "Quick Attendance" shows everyone (including Silent users) in one tappable list with search -- tap a name to check them in or out. "Search & Guest Check-In" is better for a handful of late arrivals or logging a brand-new guest visitor with intake details (phone, how they heard about the church, etc.). Both write to the same record, reviewable by date afterward.', 'L''onglet "Présences" du Tableau de bord pastoral offre deux façons d''enregistrer les présences : "Présence rapide" affiche tout le monde (y compris les utilisateurs silencieux) dans une liste à cocher avec recherche -- touchez un nom pour le marquer présent ou absent. "Recherche et accueil des invités" est mieux pour quelques retardataires ou pour enregistrer un tout nouveau visiteur avec ses informations (téléphone, comment il a connu l''église, etc.). Les deux écrivent dans le même registre, consultable par date ensuite.', 'department_admin'),

('Recording an offering', 'On the Offerings page, type the donor''s name (it autocompletes against members -- including Silent users -- so the gift can count toward their tax receipt), the date, amount, type and payment method. Leaving the name as free text still records it, just without linking to anyone''s receipt.', 'Sur la page Offrandes, saisissez le nom du donateur (saisie automatique parmi les membres -- y compris les utilisateurs silencieux -- afin que le don compte pour son reçu fiscal), la date, le montant, le type et le mode de paiement. Laisser le nom en texte libre l''enregistre quand même, simplement sans le lier au reçu de personne.', 'finance'),

('Importing past donations: two different tools', '"Import Historical Records" (on the Offerings page) recreates real offering transactions -- they show up in the ledger and monthly reports, same as entering them one by one. "Upload Donations" (on the Tax Receipts board, under Budget''s Finance tab) only writes a total toward someone''s tax receipt -- it skips the ledger entirely. Use the first to rebuild real history, the second just to fix receipt totals.', '"Importer des dossiers historiques" (page Offrandes) recrée de vraies transactions d''offrande -- elles apparaissent dans le registre et les rapports mensuels, comme si elles avaient été saisies une à une. "Téléverser des dons" (tableau des Reçus fiscaux, onglet Finances du Budget) n''inscrit qu''un total pour le reçu fiscal de quelqu''un -- il ne touche pas au registre. Utilisez le premier pour reconstituer un véritable historique, le second seulement pour corriger des totaux de reçus.', 'finance'),

('Finalizing tax receipts for a year', 'On the Tax Receipts board (Budget → Finance tab), each fiscal year shows a running total; click "Finalize" to issue receipts for everyone eligible (a legal name on file, and for a Silent member, a real email too, since a placeholder address can''t actually receive one). Anyone skipped is listed so you know who needs more info first.', 'Sur le tableau des Reçus fiscaux (Budget → onglet Finances), chaque année fiscale affiche un total courant ; cliquez sur "Finaliser" pour émettre les reçus de tous les admissibles (un nom légal enregistré, et pour un membre silencieux, aussi un vrai courriel, car une adresse temporaire ne peut pas réellement en recevoir un). Les personnes ignorées sont listées pour savoir qui a besoin de plus d''informations.', 'finance'),

('Adding a user', 'From People management, click "Add User". Fill in name, email, phone and password (or generate one), pick their department(s), and submit. Check "No login yet (Silent user)" instead if this person doesn''t need to log in yet -- see "Silent Users" for what that means.', 'Depuis la gestion des personnes, cliquez sur "Ajouter un utilisateur". Renseignez le nom, le courriel, le téléphone et le mot de passe (ou générez-en un), choisissez le ou les départements, et soumettez. Cochez "Pas encore de connexion (utilisateur silencieux)" si cette personne n''a pas encore besoin de se connecter.', 'super_admin'),

('Plans & Pricing / billing', 'From the sidebar, Super Admins can open "Plans & Pricing" to see the church''s current plan, change plans, or manage billing -- a new church starts on a free trial with no card required, and can subscribe anytime from there.', 'Depuis la barre latérale, les Super Administrateurs peuvent ouvrir "Forfaits et tarifs" pour voir le forfait actuel de l''église, en changer, ou gérer la facturation -- une nouvelle église démarre avec un essai gratuit sans carte requise, et peut s''abonner à tout moment depuis cet écran.', 'super_admin')

) as v(topic, content_en, content_fr, audience)
cross join public.tenants t;

commit;

select pg_notify('pgrst', 'reload schema');
